export interface Adventure {
  id: string;
  name: string;
  gm_password: string;
  player_link: string;
  active_image_id: string | null;
  created_at: string;
}

export interface ImageRecord {
  id: string;
  adventure_id: string;
  filename: string;
  original_name: string;
  width: number;
  height: number;
  fog_mask: Buffer | null;
  sort_order: number;
  created_at: string;
}

export interface Token {
  id: string;
  adventure_id: string;
  name: string;
  color: string;
  x: number;
  y: number;
  player_session_id: string | null;
  created_at: string;
}

import type { Database } from "bun:sqlite";

export function createSchema(db: Database): void {
  db.exec(`
    PRAGMA foreign_keys = ON;
    PRAGMA journal_mode = WAL;

    CREATE TABLE IF NOT EXISTS adventures (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      gm_password TEXT NOT NULL,
      player_link TEXT NOT NULL UNIQUE,
      active_image_id TEXT NULL REFERENCES images(id),
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS images (
      id TEXT PRIMARY KEY,
      adventure_id TEXT NOT NULL REFERENCES adventures(id) ON DELETE CASCADE,
      filename TEXT NOT NULL,
      original_name TEXT NOT NULL,
      width INTEGER NOT NULL,
      height INTEGER NOT NULL,
      fog_mask BLOB NULL,
      sort_order INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS tokens (
      id TEXT PRIMARY KEY,
      adventure_id TEXT NOT NULL REFERENCES adventures(id) ON DELETE CASCADE,
      name TEXT NOT NULL,
      color TEXT NOT NULL,
      x REAL NOT NULL DEFAULT 0,
      y REAL NOT NULL DEFAULT 0,
      player_session_id TEXT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
  `);
}

import { Database } from "bun:sqlite";
import { mkdirSync } from "fs";
import { createSchema } from "./schema";

export function initDatabase(path: string = "./data/fogofwar.db"): Database {
  if (path !== ":memory:") {
    const dir = path.substring(0, path.lastIndexOf("/"));
    if (dir) mkdirSync(dir, { recursive: true });
  }
  const db = new Database(path);
  createSchema(db);
  return db;
}

import type { Database } from "bun:sqlite";
import type { Adventure } from "../types";

export function createAdventure(
  db: Database,
  { name, gmPassword }: { name: string; gmPassword: string }
): Adventure {
  const id = crypto.randomUUID();
  const playerLink = crypto.randomUUID().replace(/-/g, "").substring(0, 8);
  db.run(
    `INSERT INTO adventures (id, name, gm_password, player_link) VALUES (?, ?, ?, ?)`,
    [id, name, gmPassword, playerLink]
  );
  return getAdventure(db, id)!;
}

export function getAdventure(db: Database, id: string): Adventure | null {
  return db.query<Adventure, string>(
    `SELECT * FROM adventures WHERE id = ?`
  ).get(id) ?? null;
}

export function getAdventureByPlayerLink(db: Database, playerLink: string): Adventure | null {
  return db.query<Adventure, string>(
    `SELECT * FROM adventures WHERE player_link = ?`
  ).get(playerLink) ?? null;
}

export function setActiveImage(db: Database, adventureId: string, imageId: string): void {
  const image = db.query<{ id: string }, [string, string]>(
    `SELECT id FROM images WHERE id = ? AND adventure_id = ?`
  ).get(imageId, adventureId);
  if (!image) throw new Error(`Image ${imageId} does not belong to adventure ${adventureId}`);
  db.run(`UPDATE adventures SET active_image_id = ? WHERE id = ?`, [imageId, adventureId]);
}

export function deleteAdventure(db: Database, id: string): void {
  db.run(`DELETE FROM adventures WHERE id = ?`, [id]);
}

import type { Database } from "bun:sqlite";
import type { ImageRecord } from "../types";

export function createImageRecord(
  db: Database,
  {
    adventureId,
    filename,
    originalName,
    width,
    height,
  }: {
    adventureId: string;
    filename: string;
    originalName: string;
    width: number;
    height: number;
  }
): ImageRecord {
  const id = crypto.randomUUID();
  db.run(
    `INSERT INTO images (id, adventure_id, filename, original_name, width, height) VALUES (?, ?, ?, ?, ?, ?)`,
    [id, adventureId, filename, originalName, width, height]
  );
  return getImage(db, id)!;
}

export function getImagesByAdventure(db: Database, adventureId: string): ImageRecord[] {
  return db.query<ImageRecord, string>(
    `SELECT * FROM images WHERE adventure_id = ? ORDER BY sort_order`
  ).all(adventureId);
}

export function getImage(db: Database, id: string): ImageRecord | null {
  return db.query<ImageRecord, string>(
    `SELECT * FROM images WHERE id = ?`
  ).get(id) ?? null;
}

export function updateFogMask(db: Database, imageId: string, mask: Buffer | null): void {
  db.run(`UPDATE images SET fog_mask = ? WHERE id = ?`, [mask, imageId]);
}

export function deleteImage(db: Database, id: string): void {
  db.run(`DELETE FROM images WHERE id = ?`, [id]);
}

import type { Database } from "bun:sqlite";
import type { Token } from "../types";

export function createToken(
  db: Database,
  { adventureId, name, color }: { adventureId: string; name: string; color: string }
