function getToken(db: Database, id: string): Token | null {
  return db.query<Token, string>(
    `SELECT * FROM tokens WHERE id = ?`
  ).get(id) ?? null;
}

export function getTokensByAdventure(db: Database, adventureId: string): Token[] {
  return db.query<Token, string>(
